<?php
session_start();require_once "../config/database.php";
if(!isset($_SESSION["user_id"])||$_SESSION["role"]!=="customer"){header("Location: ../auth/login.php");exit();}
$t=trim($_GET["tracking_id"]??"");$ship=null;$events=[];$error="";
if($t!==""){$s=$conn->prepare("SELECT * FROM shipments WHERE tracking_id=? AND customer_id=? LIMIT 1");$s->bind_param("si",$t,$_SESSION["user_id"]);$s->execute();$r=$s->get_result();if($r->num_rows===1){$ship=$r->fetch_assoc();$e=$conn->prepare("SELECT status,location,message,event_time FROM shipment_events WHERE shipment_id=? ORDER BY event_time ASC");$e->bind_param("i",$ship["id"]);$e->execute();$er=$e->get_result();while($x=$er->fetch_assoc())$events[]=$x;$e->close();}else{$error="Shipment not found for your account.";$s->close();}}
