*{box-sizing:border-box;font-family:Arial,sans-serif}body{margin:0;min-height:100vh;background:linear-gradient(135deg,#071e3d,#126e82,#1f8a70)}nav{background:#fff;padding:17px 5%;display:flex;justify-content:space-between}.logo{font-weight:bold;color:#073b4c}.nav a{margin-left:10px;text-decoration:none;color:#073b4c;font-weight:bold}.logout{background:#e63946;color:#fff!important;padding:8px;border-radius:8px}.container{width:92%;max-width:1000px;margin:40px auto}.title{color:#fff}.box{background:#fff;padding:24px;border-radius:18px;margin-top:20px}.search{display:flex;gap:10px}.search input{flex:1;padding:13px;border:2px solid #ddd;border-radius:9px}.search button{padding:13px 20px;background:#126e82;color:#fff;border:0;border-radius:9px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}.item{background:#f4fafb;padding:15px;border-radius:9px}.status{display:inline-block;padding:7px 12px;border-radius:20px;background:#e0f2fe;color:#0369a1;font-weight:bold}.timeline{border-left:3px solid #126e82;padding-left:22px}.event{margin-bottom:22px}.event h3{color:#073b4c}.event p{color:#666}.error{background:#fee2e2;color:#b91c1c;padding:13px;border-radius:8px;margin-top:20px}@media(max-width:700px){nav{flex-direction:column;gap:12px}.search{flex-direction:column}.grid{grid-template-columns:1fr}}
</style></head><body><nav><div class="logo">🚚 Smart Logistics | Customer</div><div class="nav"><a href="dashboard.php">Dashboard</a><a href="new_shipment.php">Book</a><a href="my_shipments.php">My Shipments</a><a class="logout" href="../auth/logout.php">Logout</a></div></nav><div class="container"><div class="title"><h1>📍 Track Shipment</h1><p>Enter your tracking ID.</p></div><div class="box search"><form method="GET" style="display:flex;gap:10px;width:100%"><input name="tracking_id" value="<?=htmlspecialchars($t)?>" placeholder="Tracking ID" required><button>🔎 Track</button></form></div><?php if($error):?><div class="error"><?=htmlspecialchars($error)?></div><?php endif;?><?php if($ship):?><div class="box"><h2>Shipment <?=htmlspecialchars($ship["tracking_id"])?></h2><br><div class="grid"><div class="item"><b>Sender</b><br><?=htmlspecialchars($ship["sender_name"])?></div><div class="item"><b>Receiver</b><br><?=htmlspecialchars($ship["receiver_name"])?></div><div class="item"><b>Origin</b><br><?=htmlspecialchars($ship["origin"])?></div><div class="item"><b>Destination</b><br><?=htmlspecialchars($ship["destination"])?></div><div class="item"><b>Package</b><br><?=htmlspecialchars($ship["package_type"])?></div><div class="item"><b>Weight</b><br><?=htmlspecialchars($ship["weight"])?> kg</div><div class="item"><b>Priority</b><br><?=htmlspecialchars($ship["priority"])?></div><div class="item"><b>Status</b><br><span class="status"><?=htmlspecialchars($ship["status"])?></span></div></div></div><div class="box"><h2>📜 Shipment Timeline</h2><br><div class="timeline"><?php foreach($events as $e):?><div class="event"><h3><?=htmlspecialchars($e["status"])?></h3><p>📍 <?=htmlspecialchars($e["location"])?></p><p><?=htmlspecialchars($e["message"])?></p><small><?=htmlspecialchars($e["event_time"])?></small></div><?php endforeach;?></div></div><?php endif;?></div></body></html><?php $conn->close();?>